import java.util.*;class RandomizedCollection{List<Integer>a=new ArrayList<>();Map<Integer,Set<Integer>>m=new HashMap<>();Random r=new Random();public RandomizedCollection(){}public boolean insert(int v){Set<Integer>s=m.computeIfAbsent(v,k->new HashSet<>());boolean fresh=s.isEmpty();s.add(a.size());a.add(v);return fresh;}public boolean remove(int v){Set<Integer>s=m.get(v);if(s==null||s.isEmpty())return false;int i=s.iterator().next();s.remove(i);int li=a.size()-1,last=a.get(li);a.set(i,last);if(i!=li){Set<Integer>t=m.get(last);t.remove(li);t.add(i);}a.remove(li);return true;}public int getRandom(){return a.get(r.nextInt(a.size()));}}
